theory('Introduction', 'Binary tree nodes have value, left and right references; either child may be null. Root has no parent. Height here counts nodes on a longest downward path; empty height is zero. Depth counts edges from root. A tree has no cycles or shared child nodes. Traversals visit every node in O(n): preorder root-left-right, inorder left-root-right, postorder left-right-root, level order breadth-first. General binary trees have no sorted-key property. Recursive traversals use O(h) call stack, possibly O(n) for a chain.')
for title,order in [('Inorder Traversal','I'),('Preorder Traversal','P'),('Postorder Traversal','O')]:
    body = ('out.add(r.value);' if order=='P' else '')+' walk(r.left,out); '+('out.add(r.value);' if order=='I' else '')+' walk(r.right,out); '+('out.add(r.value);' if order=='O' else '')
    add(title,tree_node+'\n    private static void walk(Node r,List<Integer> out){ if(r==null) return; '+body+' }\n    public static List<Integer> solve(Node r){ List<Integer> out=new ArrayList<>(); walk(r,out); return out; }',
        'System.out.println(solve(sample()));',{'I':'[1, 2, 3, 4, 5, 6, 7]','P':'[4, 2, 1, 3, 6, 5, 7]','O':'[1, 3, 2, 5, 7, 6, 4]'}[order],
        'Return values in '+title.lower()+'.', 'Recurse on both children, visiting the root in the position defined by this traversal. Each subtree is visited exactly once.', 'O(n) time, O(h) stack plus O(n) output.', 'For root 4 with children 2,6, the position of 4 relative to both child traversals distinguishes the three orders.', 'Null produces an empty output; values need not be unique. A deep chain can exhaust the call stack.', 'Iterative stacks avoid recursive frames but still require O(h) working storage.')
level = '''    public static List<List<Integer>> solve(Node r){ List<List<Integer>> out=new ArrayList<>(); if(r==null) return out; Queue<Node> q=new ArrayDeque<>(); q.offer(r); while(!q.isEmpty()){ int size=q.size(); List<Integer> row=new ArrayList<>(); for(int i=0;i<size;i++){ Node x=q.poll(); row.add(x.value); if(x.left!=null) q.offer(x.left); if(x.right!=null) q.offer(x.right); } out.add(row); } return out; }'''
add('Level Order Traversal',tree_node+'\n'+level,'System.out.println(solve(sample()));','[[4], [2, 6], [1, 3, 5, 7]]',
    'Return values grouped by depth, left-to-right.', 'Capture queue size before processing a level. Children enter the queue for the next level; the captured bound prevents mixing levels.', 'O(n) time/output, O(maxWidth) queue space.', 'Queue starts [4], then [2,6], then [1,3,5,7].', 'ArrayDeque forbids null; enqueue only existing children.')
add('Pre, Post, Inorder in one traversal',tree_node+'''\n    private static void visit(Node r,List<Integer> pre,List<Integer> in,List<Integer> post){ if(r==null) return; pre.add(r.value); visit(r.left,pre,in,post); in.add(r.value); visit(r.right,pre,in,post); post.add(r.value); }
    public static List<List<Integer>> solve(Node r){ List<Integer> pre=new ArrayList<>(),in=new ArrayList<>(),post=new ArrayList<>(); visit(r,pre,in,post); return Arrays.asList(pre,in,post); }''','System.out.println(solve(sample()));','[[4, 2, 1, 3, 6, 5, 7], [1, 2, 3, 4, 5, 6, 7], [1, 3, 2, 5, 7, 6, 4]]',
    'Return [preorder,inorder,postorder] from a single recursive walk.', 'Record a root at entry, between children, and at exit respectively. These are the three natural phases of a depth-first call.', 'O(n) time and output, O(h) stack.', 'At root 4: pre records 4 before left, in after left, post after right.', 'The returned order of the three lists is explicit and may differ from another platform\'s API.')
height='''    static int height(Node r){ return r==null?0:1+Math.max(height(r.left),height(r.right)); }'''
tree_rows=[
 ('Maximum Depth in BT','int','Node r','return height(r);','sample()','3','Longest root-to-leaf path in NODES; empty depth is zero.','A subtree height is one plus the larger child height.'),
 ('Check if two trees are identical or not','boolean','Node a,Node b','if(a==null||b==null) return a==b; return a.value==b.value&&solve(a.left,b.left)&&solve(a.right,b.right);','sample(),sample()','true','Check equal structure and values.','Both null matches; one null fails; otherwise roots and both corresponding subtrees must match.'),
 ('Check for symmetrical BTs','boolean','Node r','return r==null||mirror(r.left,r.right);','sample()','false','Check mirror symmetry of structure AND values about the root.','Compare the left child of one side with the right child of the other.'),
 ('Children Sum Property in Binary Tree','boolean','Node r','if(r==null||r.left==null&&r.right==null) return true; long sum=(r.left==null?0L:r.left.value)+(r.right==null?0L:r.right.value); return r.value==sum&&solve(r.left)&&solve(r.right);','sample()','false','Check whether each nonleaf value equals its children\'s values, with missing child zero.','Test local equality and recursively require it at all descendants. This lesson checks the property; it does not increase values to enforce it.')]
mirror='''    static boolean mirror(Node a,Node b){ if(a==null||b==null) return a==b; return a.value==b.value&&mirror(a.left,b.right)&&mirror(a.right,b.left); }'''
for title,typ,params,body,call,expected,contract,reason in tree_rows:
    add(title,tree_node+'\n'+height+'\n'+mirror+'\n    public static %s solve(%s){ %s }'%(typ,params,body),'System.out.println(solve(%s));'%call,expected,contract,reason,
        'O(n) time, O(h) recursion space.', 'Sample tree has three levels; its unequal mirrored values and root 4 != 2+6 make symmetry/children-sum checks false.', 'Be explicit about checking versus modifying the children-sum property. An empty tree passes boolean structural checks.')
add('Check for balanced binary tree',tree_node+'''\n    static int balancedHeight(Node r){ if(r==null) return 0; int l=balancedHeight(r.left); if(l<0) return -1; int q=balancedHeight(r.right); if(q<0||Math.abs(l-q)>1) return -1; return 1+Math.max(l,q); }
    public static boolean solve(Node r){ return balancedHeight(r)>=0; }''','System.out.println(solve(sample()));','true',
    'Every node\'s two subtree heights must differ by at most one.', 'Return height when balanced, or -1 sentinel for imbalance. Postorder computes each child height once and propagates failure.', 'O(n) time, O(h) stack.', 'Sample child heights are equal at every internal node.', 'Checking only root balance is insufficient.', 'Recomputing subtree height at each node is O(n²) worst time.')
add('Diameter of Binary Tree',tree_node+'''\n    static int depth(Node r,int[] best){ if(r==null) return 0; int l=depth(r.left,best),q=depth(r.right,best); best[0]=Math.max(best[0],l+q); return 1+Math.max(l,q); }
    public static int solve(Node r){ int[] best={0}; depth(r,best); return best[0]; }''','System.out.println(solve(sample()));','4',
    'Return the longest path length in EDGES between any two nodes.', 'A longest path has a highest node where its left and right downward paths meet. For each root, child heights sum to its through-root edge count; maximize globally.', 'O(n) time, O(h) stack.', 'Leaf 1 ->2->4->6->7 has four edges.', 'A diameter need not pass through the global root. Singleton diameter is zero.')
add('Maximum path sum',tree_node+'''\n    private static long gain(Node r,long[] best){ if(r==null) return 0; long l=Math.max(0,gain(r.left,best)),q=Math.max(0,gain(r.right,best)); best[0]=Math.max(best[0],r.value+l+q); return r.value+Math.max(l,q); }
    public static long solve(Node r){ if(r==null) throw new IllegalArgumentException(); long[] best={Long.MIN_VALUE}; gain(r,best); return best[0]; }''','System.out.println(solve(sample()));','22',
    'Return maximum sum of a NONEMPTY simple path in a nonempty binary tree.', 'Negative child gains can be omitted. Update the complete path using both sides, but return only one side because a parent cannot extend a fork.', 'O(n) time, O(h) stack.', '3->2->4->6->7 sums 22 in the sample.', 'Initialize global best to -infinity for all-negative trees, and use long sums.')
add('Zig Zag or Spiral Traversal',tree_node+'\n'+level.replace('solve(Node r)','levels(Node r)')+'''\n    public static List<List<Integer>> solve(Node r){ List<List<Integer>> out=levels(r); for(int i=1;i<out.size();i+=2) Collections.reverse(out.get(i)); return out; }''','System.out.println(solve(sample()));','[[4], [6, 2], [1, 3, 5, 7]]',
    'Return level order alternating left-to-right then right-to-left.', 'Compute level groups with BFS, then reverse odd-indexed levels. Reversal changes ordering only, preserving depth membership.', 'O(n) time/output, O(maxWidth) queue.', 'Level 0 [4], reverse level 1 to [6,2], level 2 stays [1,3,5,7].', 'Do not reverse child enqueue order without a carefully matched traversal invariant.')
leaf='''    static boolean leaf(Node r){return r!=null&&r.left==null&&r.right==null;}
    static void leaves(Node r,List<Integer> a){if(r==null) return; if(leaf(r)){a.add(r.value);return;} leaves(r.left,a); leaves(r.right,a);}'''
add('Boundary Traversal',tree_node+'\n'+leaf+'''\n    public static List<Integer> solve(Node r){ List<Integer> out=new ArrayList<>(); if(r==null) return out; if(!leaf(r)) out.add(r.value); for(Node p=r.left;p!=null;p=p.left!=null?p.left:p.right) if(!leaf(p)) out.add(p.value); leaves(r,out); List<Integer> right=new ArrayList<>(); for(Node p=r.right;p!=null;p=p.right!=null?p.right:p.left) if(!leaf(p)) right.add(p.value); Collections.reverse(right); out.addAll(right); return out; }''','System.out.println(solve(sample()));','[4, 2, 1, 3, 5, 7, 6]',
    'Anticlockwise boundary: root, left boundary excluding leaves, leaves left-to-right, reversed right boundary excluding leaves.', 'Collect each role separately. Excluding leaves from boundaries prevents duplication; root is omitted initially if it is itself a leaf.', 'O(n) time/output, O(h) recursion/boundary space.', 'Sample: root 4; left boundary 2; leaves 1,3,5,7; reversed right boundary 6.', 'For missing left/right children use the available child while following a boundary.')
positions = '''    static class Position { Node n; int col,row; Position(Node n,int c,int r){this.n=n;col=c;row=r;} }
    static List<Position> positions(Node root){ List<Position> out=new ArrayList<>(); if(root==null) return out; Queue<Position> q=new ArrayDeque<>(); q.offer(new Position(root,0,0)); while(!q.isEmpty()){ Position p=q.poll(); out.add(p); if(p.n.left!=null) q.offer(new Position(p.n.left,p.col-1,p.row+1)); if(p.n.right!=null) q.offer(new Position(p.n.right,p.col+1,p.row+1)); } return out; }'''
add('Vertical Order Traversal',tree_node+'\n'+positions+'''\n    public static List<List<Integer>> solve(Node r){ List<Position> all=positions(r); all.sort((a,b)->{ int c=Integer.compare(a.col,b.col); if(c==0)c=Integer.compare(a.row,b.row); if(c==0)c=Integer.compare(a.n.value,b.n.value); return c; }); List<List<Integer>> out=new ArrayList<>(); Integer col=null; for(Position p:all){ if(col==null||p.col!=col){ out.add(new ArrayList<>()); col=p.col; } out.get(out.size()-1).add(p.n.value); } return out; }''','System.out.println(solve(sample()));','[[1], [2], [4, 3, 5], [6], [7]]',
    'Group by horizontal column; within a column sort by depth, then value for same depth.', 'Assign coordinates root(0,0), left(-1,+1), right(+1,+1). Sort the coordinate records by the exact tie rules and group equal columns.', 'O(n log n) time and O(n) space.', 'Column zero contains 4 at depth 0 and values 3,5 at depth 2.', 'BFS order alone is insufficient when same-coordinate ties require numeric order.')
for title,bottom in [('Top View of BT',False),('Bottom view of BT',True)]:
    body='map.put(p.col,p.n.value);' if bottom else 'map.putIfAbsent(p.col,p.n.value);'
    add(title,tree_node+'\n'+positions+'\n    public static List<Integer> solve(Node r){ Map<Integer,Integer> map=new TreeMap<>(); for(Position p:positions(r)){ '+body+' } return new ArrayList<>(map.values()); }','System.out.println(solve(sample()));','[1, 2, 5, 6, 7]' if bottom else '[1, 2, 4, 6, 7]',
        'Return one visible value per column from left to right. Bottom-view equal-depth ties choose the later BFS node.', 'BFS visits shallow nodes first. %s TreeMap emits columns in ascending order.'%('Overwrite per column to retain the latest/deepest.' if bottom else 'Retain the first per column for the shallowest.'),
        'O(n log n) time and O(n) space.', 'Column zero has 4 first, then 3 and 5; top retains 4, bottom retains 5.', 'Tie rules vary by platform; bottom here uses later left-to-right BFS order.')
add('Right/Left View of BT',tree_node+'\n'+level.replace('solve(Node r)','levels(Node r)')+'''\n    public static List<List<Integer>> solve(Node r){ List<Integer> left=new ArrayList<>(),right=new ArrayList<>(); for(List<Integer> row:levels(r)){ left.add(row.get(0)); right.add(row.get(row.size()-1)); } return Arrays.asList(right,left); }''','System.out.println(solve(sample()));','[[4, 6, 7], [4, 2, 1]]',
    'Return [rightView,leftView], one visible value per depth.', 'The last and first values respectively in each left-to-right BFS level define the views.', 'O(n) time/space.', 'Sample right edges 4,6,7; left edges 4,2,1.', 'Horizontal columns used for top/bottom views do not define side views.')
add('Print root to leaf path in BT',tree_node+'''\n    private static void dfs(Node r,List<Integer> p,List<List<Integer>> out){ if(r==null) return; p.add(r.value); if(r.left==null&&r.right==null) out.add(new ArrayList<>(p)); else { dfs(r.left,p,out); dfs(r.right,p,out); } p.remove(p.size()-1); }
    public static List<List<Integer>> solve(Node r){ List<List<Integer>> out=new ArrayList<>(); dfs(r,new ArrayList<>(),out); return out; }''','System.out.println(solve(sample()));','[[4, 2, 1], [4, 2, 3], [4, 6, 5], [4, 6, 7]]',
    'Return all full root-to-leaf paths, left-first.', 'DFS appends current value; copy at a leaf, recurse otherwise, then remove current before returning.', 'O(n+total emitted path lengths) time; O(h) working state plus output.', 'Path 4,2 branches into leaves 1 and 3; after backtracking 4,6 branches into 5 and 7.', 'A leaf has neither child. Copy paths rather than storing the shared mutable builder.')
add('LCA in BT',tree_node+'''\n    public static Node solve(Node r,Node a,Node b){ if(r==null||r==a||r==b) return r; Node l=solve(r.left,a,b),q=solve(r.right,a,b); return l!=null&&q!=null?r:l!=null?l:q; }''','Node r=sample(); System.out.println(solve(r,r.left.left,r.left.right).value);','2',
    'Find lowest common ancestor by NODE identity; both query nodes must exist in the tree.', 'A subtree returns a found query or its LCA. If both children return nonnull, current root is the first meeting point; otherwise propagate the single found side.', 'O(n) time; O(h) stack.', 'Queries nodes 1 and 3 lie in opposite children of node 2, so LCA is 2.', 'Equal values do not imply the same node. If either node may be absent, validate membership first; this kernel assumes presence.')
add('Maximum Width of BT',tree_node+'''\n    static class Indexed { Node n; BigInteger i; Indexed(Node n,BigInteger i){this.n=n;this.i=i;} }
    public static BigInteger solve(Node r){ if(r==null) return BigInteger.ZERO; Queue<Indexed> q=new ArrayDeque<>(); q.offer(new Indexed(r,BigInteger.ZERO)); BigInteger best=BigInteger.ONE; while(!q.isEmpty()){ int size=q.size(); BigInteger base=q.peek().i,last=BigInteger.ZERO; for(int j=0;j<size;j++){ Indexed p=q.poll(); BigInteger i=p.i.subtract(base); last=i; if(p.n.left!=null) q.offer(new Indexed(p.n.left,i.shiftLeft(1))); if(p.n.right!=null) q.offer(new Indexed(p.n.right,i.shiftLeft(1).add(BigInteger.ONE))); } best=best.max(last.add(BigInteger.ONE)); } return best; }''','System.out.println(solve(sample()));','4',
    'Width includes missing positions between leftmost/rightmost existing nodes at a level; return exact BigInteger.', 'Assign conceptual complete-tree indices. Normalize each level by its first index, preserving differences. Width is last normalized index+1. BigInteger avoids exponential-gap overflow.', 'O(n) index operations plus index bit costs; O(maxWidthInNodes) queue storage.', 'Full sample last level has indices 0,1,2,3, width four.', 'Count of actual level nodes differs from indexed width on sparse trees. Even normalization alone cannot prevent long overflow for very wide sparse gaps.')
parents = '''    static Map<Node,Node> parents(Node root){ Map<Node,Node> parent=new IdentityHashMap<>(); if(root==null) return parent; Queue<Node> q=new ArrayDeque<>(); q.offer(root); parent.put(root,null); while(!q.isEmpty()){ Node p=q.poll(); if(p.left!=null){ parent.put(p.left,p); q.offer(p.left); } if(p.right!=null){ parent.put(p.right,p); q.offer(p.right); } } return parent; }
    static List<List<Node>> outward(Node root,Node target){ Map<Node,Node> parent=parents(root); if(!parent.containsKey(target)) throw new IllegalArgumentException("target not in tree"); Set<Node> seen=Collections.newSetFromMap(new IdentityHashMap<Node,Boolean>()); Queue<Node> q=new ArrayDeque<>(); q.offer(target); seen.add(target); List<List<Node>> out=new ArrayList<>(); while(!q.isEmpty()){ List<Node> row=new ArrayList<>(); for(int size=q.size();size>0;size--){ Node p=q.poll(); row.add(p); for(Node next:new Node[]{p.left,p.right,parent.get(p)}) if(next!=null&&seen.add(next)) q.offer(next); } out.add(row); } return out; }'''
add('Print all nodes at a distance of K in BT',tree_node+'\n'+parents+'''\n    public static List<Integer> solve(Node root,Node target,int k){ if(k<0) throw new IllegalArgumentException(); List<List<Node>> layers=outward(root,target); List<Integer> out=new ArrayList<>(); if(k<layers.size()) for(Node n:layers.get(k)) out.add(n.value); return out; }''','Node r=sample(); System.out.println(solve(r,r.left,2));','[6]',
    'Return values exactly k edges from a given target node; target must be in the tree.', 'Map parent links, then BFS from target using left,right,parent as graph neighbors. Identity-based seen prevents walking back and forth; layer k is distance k.', 'O(n) time/space (this teaching helper computes all layers).', 'From node 2: layer 0 [2], layer 1 [1,3,4], layer 2 [6].', 'An optimized distance-k BFS can stop after k layers. Equal values remain separate node identities.')
add('Minimum time taken to burn the BT from a given Node',tree_node+'\n'+parents+'\n    public static int solve(Node root,Node target){ return outward(root,target).size()-1; }','Node r=sample(); System.out.println(solve(r,r.left.left));','4',
    'Fire starts at target at time zero and spreads one edge per unit time; return time until all tree nodes burn.', 'Reuse undirected BFS from the target. The last layer number is the farthest distance, which determines completion time.', 'O(n) time/space.', 'From leaf 1, leaf 7 is reached via 1,2,4,6,7 at time four.', 'The result counts elapsed edges, not number of layers. Target membership is validated.')
add('Count total nodes in a complete BT',tree_node+'''\n    public static long solve(Node r){ if(r==null) return 0; int left=0,right=0; for(Node p=r;p!=null;p=p.left) left++; for(Node p=r;p!=null;p=p.right) right++; if(left==right){ if(left>=63) throw new ArithmeticException("count exceeds long"); return (1L<<left)-1; } return 1+solve(r.left)+solve(r.right); }''','System.out.println(solve(sample()));','7',
    'Count nodes in a COMPLETE binary tree; incomplete arbitrary trees violate this shortcut\'s contract.', 'In a complete subtree, equal leftmost/rightmost heights prove it is perfect, with 2^height-1 nodes. Otherwise recurse; at least one side is perfect at each level.', 'O(log² n) time; O(log n) stack on complete trees.', 'Sample extreme heights both three, so 2³-1=7.', 'Equal extreme heights alone do not prove perfection for arbitrary trees; completeness is essential. Shift overflow is explicitly rejected.')
add('Flatten Binary Tree to Linked List',tree_node+'''\n    public static void solve(Node r){ for(Node p=r;p!=null;p=p.right){ if(p.left!=null){ Node last=p.left; while(last.right!=null) last=last.right; last.right=p.right; p.right=p.left; p.left=null; } } }''','Node r=sample(); solve(r); List<Integer> a=new ArrayList<>(); for(Node p=r;p!=null;p=p.right) a.add(p.value); System.out.println(a);','[4, 2, 1, 3, 6, 5, 7]',
    'Flatten in place into preorder order along right links; every left becomes null.', 'Splice each left subtree before the current right subtree, attaching old right to its rightmost boundary. This preserves root-left-right visitation.', 'O(n) amortized time; O(1) space.', 'Root 4 places left subtree 2 before 6; node 2 places 1 before 3; final right chain is preorder.', 'The original shape is destroyed. Returned chain reuses existing node identities.')
theory('Requirements needed to construct a unique BT', 'With DISTINCT labels, inorder plus preorder or inorder plus postorder uniquely determines a binary tree. Root comes from preorder first or postorder last; its inorder position divides left/right labels. Preorder plus postorder generally does not identify whether a lone child is left or right, so it is not unique without extra structural assumptions (such as full binary tree). Duplicate labels break unique index lookup and may admit multiple trees. Level order alone is also insufficient. Validate traversal lengths, labels and consistent subtree ranges; do not silently construct from mismatched inputs.')
build_tree = '''    private static Node build(int[] order,int ol,int or,int il,int ir,Map<Integer,Integer> index,boolean pre){ if(ol>=or) return null; int value=order[pre?ol:or-1]; Integer split=index.get(value); if(split==null||split<il||split>=ir) throw new IllegalArgumentException("inconsistent traversals"); int size=split-il; Node r=new Node(value); if(pre){ r.left=build(order,ol+1,ol+1+size,il,split,index,true); r.right=build(order,ol+1+size,or,split+1,ir,index,true); } else { r.left=build(order,ol,ol+size,il,split,index,false); r.right=build(order,ol+size,or-1,split+1,ir,index,false); } return r; }
    public static Node solve(int[] order,int[] in){ if(order.length!=in.length) throw new IllegalArgumentException(); Map<Integer,Integer> index=new HashMap<>(); for(int i=0;i<in.length;i++) if(index.put(in[i],i)!=null) throw new IllegalArgumentException("duplicate labels"); return build(order,0,order.length,0,in.length,index,PRE); }'''
for title,pre in [('Construct a BT from Preorder and Inorder',True),('Construct a BT from Postorder and Inorder',False)]:
    add(title,tree_node+'\n'+build_tree.replace('PRE',str(pre).lower()),'System.out.println(view(solve(new int[]{%s},new int[]{1,2,3})));'%('2,1,3' if pre else '1,3,2'),'[1, 2, 3]',
        'Construct using distinct labels, supplied traversal order then inorder. Reject inconsistent intervals and lengths.', 'Root is at the beginning of preorder or end of postorder. Look up its inorder position to determine left size and recurse on corresponding half-open ranges.', 'Expected O(n) time with index map; O(n) map/output plus O(h) stack.', 'For inorder 1,2,3, root 2 divides leaf 1 from leaf 3.', 'Duplicates are explicitly unsupported. Repeated linear inorder scans would cost O(n²) in a skewed case.')
add('Serialize and De-serialize BT',tree_node+'''\n    static void encode(Node r,StringBuilder s){ if(r==null){ s.append("#, "); return; } s.append(r.value).append(", "); encode(r.left,s); encode(r.right,s); }
    public static String serialize(Node r){ StringBuilder s=new StringBuilder(); encode(r,s); return s.toString(); }
    static Node decode(String[] tokens,int[] at){ if(at[0]>=tokens.length) throw new IllegalArgumentException(); String t=tokens[at[0]++].trim(); if(t.equals("#")) return null; Node r=new Node(Integer.parseInt(t)); r.left=decode(tokens,at); r.right=decode(tokens,at); return r; }
    public static Node deserialize(String s){ String[] tokens=s.trim().split(","); int[] at={0}; Node r=decode(tokens,at); if(at[0]!=tokens.length) throw new IllegalArgumentException(); return r; }''','Node r=sample(); System.out.println(view(deserialize(serialize(r))));','[1, 2, 3, 4, 5, 6, 7]',
    'Round-trip tree shape and int values using preorder with # for each null reference.', 'Null markers make structure unambiguous. Decoder consumes one token for a root, then exactly its left and right encodings.', 'O(n) token work/string size, O(h) stack plus O(n) output tree.', 'Leaf 1 encodes 1,#,#; attaching subtree encodings recovers every missing child.', 'Inorder values alone cannot recover shape. Decoder rejects missing/extra tokens; token strings are untrusted data, never executable instructions.')
for title,pre in [('Morris Inorder Traversal',False),('Morris Preorder Traversal',True)]:
    code='''    public static List<Integer> solve(Node r){ List<Integer> out=new ArrayList<>(); while(r!=null){ if(r.left==null){ out.add(r.value); r=r.right; } else { Node before=r.left; while(before.right!=null&&before.right!=r) before=before.right; if(before.right==null){ ON_ENTER before.right=r; r=r.left; } else { before.right=null; ON_EXIT r=r.right; } } } return out; }'''.replace('ON_ENTER','out.add(r.value);' if pre else '').replace('ON_EXIT','' if pre else 'out.add(r.value);')
    add(title,tree_node+'\n'+code,'System.out.println(solve(sample()));','[4, 2, 1, 3, 6, 5, 7]' if pre else '[1, 2, 3, 4, 5, 6, 7]',
        'Traverse with O(1) auxiliary state by temporarily threading pointers; original links are restored on normal completion.', 'For a left subtree, thread its rightmost node back to root. First encounter creates the thread and descends; second removes it. %s'%('Preorder records root on first encounter.' if pre else 'Inorder records root after the left subtree completes.'),
        'O(n) amortized time, O(1) auxiliary space excluding O(n) result.', 'At 4, temporarily set 3.right=4; after traversing 2, remove that thread and continue to 6.', 'Do not stop early or throw while threads remain; that would corrupt the tree. Concurrent traversal is unsafe during threading.')
